    const redraw = async () => { await m.evaluate(() => { document.querySelector('#s-cart .pfield')._old = 1; const u = [...document.querySelectorAll('#s-cart .ups')].find(e => e.getClientRects().length); u.click(); }); await m.waitForTimeout(1500);
        return m.evaluate(() => !document.querySelector('#s-cart .pfield')._old); };
