    const look = await m.evaluate(() => { const ok = document.querySelector('.lang.is-on .lang__ok'), off = document.querySelector('.lang:not(.is-on) .lang__ok path'), c = ok ? getComputedStyle(ok).color.match(/\d+/g).map(Number) : [0, 0, 0];
        return { soon: !!document.querySelector('.lang__soon'), head: !!document.querySelector('.lang__h'), flags: document.querySelectorAll('.langs .lang__f svg').length, green: c[1] > c[0] + 40 && c[1] > c[2], dot: off ? getComputedStyle(off).opacity : '?' }; });
