    const SUBS = 'беларуская мова|русский язык|English language · phone language';
    if (a.map(x => x.name).join('|') !== 'Мова|Язык|English' || a.map(x => x.sub).join('|') !== SUBS || !(a[2] && a[2].on) || a.filter(x => x.on).length !== 1) bad.push('строки выбора: ' + JSON.stringify(a));
    if (look.soon || look.head || look.flags !== 3 || !look.green || look.dot !== '0') bad.push('вид выбора (флаги, без заголовка и «скоро», зелёная галочка без точки): ' + JSON.stringify(look));
    // 07.11: «иконки языков — маленькими, как другие иконки в профиле, и рядом с заголовком»: флаг ≤ 24 px, по центру строки заголовка
    const fl = await m.evaluate(() => [...document.querySelectorAll('.langs .lang')].map(b => { const f = b.querySelector('.lang__f').getBoundingClientRect(), t = b.querySelector('.lang__t b').getBoundingClientRect(); return { w: Math.round(f.width), dy: Math.round((f.top + f.height / 2) - (t.top + t.height / 2)) }; }));
    if (fl.some(x => x.w > 24 || Math.abs(x.dy) > 3)) bad.push('флаги: ' + JSON.stringify(fl));
