    await m.evaluate(() => { window.__prof = document.querySelector('#profileScroll').firstElementChild; document.querySelector('.lang[data-id="be"]').click(); });
    await m.waitForTimeout(260);
    const b0 = await m.evaluate(() => ({ on: document.querySelector('.lang[data-id="be"]').classList.contains('is-on'), off: !document.querySelector('.lang[data-id="en"]').classList.contains('is-on'), dash: parseFloat(getComputedStyle(document.querySelector('.lang[data-id="be"] .lang__ok path')).strokeDashoffset) }));
    if (!b0.on || !b0.off || !(b0.dash > .02 && b0.dash < .99)) bad.push('галочка не переехала с анимацией: ' + JSON.stringify(b0));
    await m.waitForTimeout(110);
    const dim = await m.evaluate(() => Math.min.apply(0, [...document.querySelectorAll('#profileScroll > .sec')].map(e => +getComputedStyle(e).opacity)));
    if (!(dim < .5)) bad.push('экран не погас: ' + dim);
    await m.waitForTimeout(690);
    const b = await m.evaluate(() => ({ rows: [...document.querySelectorAll('.langs .lang')].map(x => x.querySelector('.lang__t b').textContent + ' / ' + x.querySelector('.lang__t small').textContent.replace(/\s+/g, ' ')).join('; '),
        subs: [...document.querySelectorAll('.langs .lang__t small')].map(x => x.textContent.replace(/\s+/g, ' ')).join('|'), same: window.__prof === document.querySelector('#profileScroll').firstElementChild, tabs: [...document.querySelectorAll('#tabbar .tab span:last-child')].map(s => s.textContent.replace(/[\s\u00a0]+/g, ' ').trim()).join('|'), ttl: document.querySelector('#profileScroll .ttl').textContent, stored: localStorage.getItem('clever2-lang'), lang: document.documentElement.lang }));
    if (!b.same || b.tabs !== 'Галоўная|Профіль|Пошук|Абранае|Мая замова' || b.ttl !== 'Профіль' || b.stored !== 'be' || b.lang !== 'be') bad.push('после выбора: ' + JSON.stringify(b));
    if (b.subs !== SUBS) bad.push('подписи строк выбора сменили язык вместе с интерфейсом: ' + b.subs);   // каждая — на своём языке
    out.push('профиль: ' + a.map(x => x.name + ' («' + x.sub + '»)' + (x.on ? '✓' : '')).join(', ') + ' (флаги, галочка зелёная) → «Мова»: экран погас (' + dim.toFixed(2) + ') и зажёгся, ' + b.tabs + '; подписи строк — те же: ' + b.rows);
    await m._close();
    const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, locale: 'ru-RU' }), p2 = await ctx.newPage();
    await p2.route(/unpkg\.com\/maplibre-gl/, r => r.fulfill({ body: MAPLIB, contentType: 'application/javascript' })); await p2.route(/tiles\.openfreemap\.org/, r => r.fulfill({ body: STYLE, contentType: 'application/json' }));
