    const c = await p2.evaluate(() => ({ lang: document.documentElement.lang, head: ((document.querySelector('#s-home .addr small') || {}).textContent || '').replace(/[\s\u00a0]+/g, ' ').trim() }));
    if (c.lang !== 'be' || c.head !== 'Дастаўка · Мінск') bad.push('перезапуск с телефоном ru-RU: ' + JSON.stringify(c));
    await ctx.close();
    return { pass: !bad.length, detail: out.join('; ') + (bad.length ? '; ✗ ' + bad.join('; ') : '') };
