    if (n1 > 90 || !plan) bad.push('«Ко времени»: раскладок ' + n1 + (plan ? '' : ', высота — переходом'));
    out.push('«Ко времени»: раскладок ' + n1 + ' за 0,9 с (было 165)');
    // «Наличными»: капсулы не выходят за видимую часть карточки
    await m.evaluate(() => { const sc = document.querySelector('#s-checkout .scroll'), p = document.querySelector('#pay-cash'); sc.scrollTop += p.getBoundingClientRect().top - 200; }); await m.waitForTimeout(300);
    await m.evaluate(() => document.querySelector('#pay-cash').click());
    let worst = 0;
    for (let i = 0; i < 8; i++) { await m.waitForTimeout(90);
        worst = Math.max(worst, await m.evaluate(() => { const card = document.querySelector('#s-checkout .cpay__more[data-more="cash"]').closest('.bt, .cgrp'), cr = card.getBoundingClientRect(), cp = getComputedStyle(card).clipPath, ins = /inset\(\S+ \S+ ([\d.]+)px/.exec(cp), bot = cr.bottom - (ins ? +ins[1] : 0);
            const mi = document.querySelector('#s-checkout .cpay__more[data-more="cash"] .cpay__mi'), mr = mi.getBoundingClientRect(), clipMi = getComputedStyle(mi).overflow !== 'visible';
            return [...document.querySelectorAll('#s-checkout .cchg')].reduce((a, b) => { const r = b.getBoundingClientRect(), op = +getComputedStyle(b).opacity; if (op < .2) return a; return Math.max(a, r.bottom - bot, clipMi ? r.bottom - mr.bottom : 0, clipMi ? mr.top - r.top : 0); }, 0); })); }
    if (worst > 1) bad.push('капсулы сдачи обрезаны на ' + worst.toFixed(1) + ' px');
    out.push('сдача: края не обрезаны');
