    await m.evaluate(() => { const sc = document.querySelector('#s-checkout .scroll'), n = document.getElementById('f-note'); sc.scrollTop += n.getBoundingClientRect().top - 300; n.focus(); }); await m.waitForTimeout(300);
    const hs = []; await m.evaluate(() => { const n = document.getElementById('f-note'); window.__nh = []; new MutationObserver(() => window.__nh.push(n.style.height)).observe(n, { attributes: true, attributeFilter: ['style'] }); });
    await m.keyboard.type('Домофон 14, второй подъезд со двора, код 1234, позвоните заранее — во дворе шлагбаум', { delay: 20 });
    await m.waitForTimeout(400);
