    await m.evaluate(() => document.querySelector('#tabbar .tab[data-tab="profile"]').click()); await m.waitForTimeout(900);
    await m.evaluate(() => document.querySelector('#profileScroll .cseg[data-key="theme"]').scrollIntoView({ block: 'center' })); await m.waitForTimeout(300);
    const T = '#profileScroll .cseg[data-key="theme"]';
    await drag(T, 1.8); const t1 = await m.evaluate(() => (document.documentElement.getAttribute('data-theme') || 'auto'));
    await drag(T, -1.1); const t2 = await m.evaluate(() => (document.documentElement.getAttribute('data-theme') || 'auto'));
    const icon = await m.evaluate(() => (document.querySelector('#profileScroll .thm') || {}).getAttribute && document.querySelector('#profileScroll .thm').getAttribute('data-k'));
    if (t1 !== 'dark' || t2 !== 'auto' || icon !== 'auto') bad.push('тема: ' + JSON.stringify({ t1, t2, icon }));
    out.push('тема: ' + t1 + ' → ' + t2 + ' (значок ' + icon + ')');
