    const st = () => m.evaluate(() => { const t = document.querySelector('#s-checkout .bt--pick'); if (!t) return null; const P = [...t.querySelectorAll('.pk__pin')];
        return { pins: P.length, inside: P.every(p => { const r = p.getBoundingClientRect(), b = t.querySelector('.pk__map').getBoundingClientRect(); return r.left >= b.left - 2 && r.right <= b.right + 2 && r.top >= b.top - 2; }),
            on: (t.querySelector('.pk__pin.is-on') || {}).dataset.id, chip: [...t.querySelectorAll('.pk__pt[aria-pressed="true"]')].map(x => x.dataset.id).join(), addr: t.querySelector('.pk__st').textContent.replace(/⁠/g, '') }; });
