    await m.evaluate(() => document.querySelector('#s-checkout [data-act="mode"][data-id="pickup"]').click()); await m.waitForTimeout(900);
    const s3 = await st();
    if (!s0 || s0.pins < 2 || !s0.inside || s0.on !== s0.chip) bad.push('сначала: ' + JSON.stringify(s0));
