    if (r0 !== '3 новых') bad.push('профиль: «' + r0 + '»');
    await m.evaluate(() => document.querySelector('#profileScroll [data-act="go-notif"]').click()); await m.waitForTimeout(1500);
    const a = await m.evaluate(() => { const S = '#s-notif ', all = [...document.querySelectorAll(S + '.nt')], g = document.querySelector('#s-notif > .bar .bar__gear'), gr = g ? g.getBoundingClientRect() : null, bar = document.querySelector('#s-notif > .bar').getBoundingClientRect(), tt = document.querySelector('#s-notif > .bar .bar__title').getBoundingClientRect();
        return { n: all.length, nw: document.querySelectorAll(S + '.nt.is-new').length, days: document.querySelectorAll(S + '.omon').length, setIn: document.querySelectorAll(S + '.nts__set, ' + S + '.ckeep').length, old: document.querySelectorAll(S + '.tk, ' + S + '.nt__card, ' + S + '.nt__from').length,
            gear: gr ? { right: Math.round(bar.right - gr.right), mid: Math.round(gr.top + gr.height / 2 - (tt.top + tt.height / 2)), w: Math.round(gr.width) } : null, readInBar: !!document.querySelector('#s-notif > .bar [data-act="notif-read"]'), read: !!document.querySelector('#ntList [data-act="notif-read"]'),
            cards: all.map(e => { const q = s => e.querySelector(s), t = q('.nt__t'), s = q('.nt__s'), pic = q('.nt__pic'), pr = pic ? pic.getBoundingClientRect() : null; return { id: e.dataset.id, ok: !!(q('.nt__head > .nt__ic') && t && s && q('.nt__head > .nt__time')), h: Math.round(e.getBoundingClientRect().height), th: Math.round(t.getBoundingClientRect().height), sh: Math.round(s.getBoundingClientRect().height), pic: pr ? Math.round(pr.width) + '×' + Math.round(pr.height) : '', more: getComputedStyle(q('.nt__more')).display }; }) }; });
