    if (!a.gear || a.gear.right > 16 || a.gear.right < 0 || Math.abs(a.gear.mid) > 3 || a.gear.w < 36) bad.push('значок настроек — не в правом верхнем углу: ' + JSON.stringify(a.gear));
    if (a.readInBar || !a.read) bad.push('«Прочитать все» — не на строке первого дня');
    const tall = a.cards.filter(c => !c.ok || c.h > 92 || c.h < 60 || c.th > 21 || c.sh > 39 || c.more !== 'none');
    if (tall.length) bad.push('карточки не в одном компактном виде: ' + JSON.stringify(tall));
    const pics = a.cards.filter(c => c.pic);
    if (pics.length !== 4 || pics.some(c => c.pic !== '44×44')) bad.push('миниатюры картинок: ' + JSON.stringify(pics.map(c => c.id + ' ' + c.pic)));
    out.push('уведомлений ' + a.n + ', новых ' + a.nw + ', дней ' + a.days + '; все карточки одного вида, ' + Math.min(...a.cards.map(c => c.h)) + '–' + Math.max(...a.cards.map(c => c.h)) + ' px (заголовок в строку, текст ≤ 2 строк), с миниатюрой — ' + pics.length + '; настройки — значком справа сверху');
    // касание — раскрывается на месте: высота едет, картинка крупно, кнопка действия; точка «новое» гаснет
    const h0 = a.cards.find(c => c.id === 'n2').h;
    const o1 = await m.evaluate(() => { const e = document.querySelector('#s-notif .nt[data-id="n2"]'); e.querySelector('.nt__head').click(); const an = e.getAnimations().find(x => x.effect.getKeyframes().some(k => k.height)); return { kf: an ? an.effect.getKeyframes().map(k => k.height) : null, ms: an ? an.effect.getTiming().duration : 0 }; });
    if (!o1.kf || parseFloat(o1.kf[0]) !== h0 || parseFloat(o1.kf[1]) < h0 + 150 || o1.ms < 250 || o1.ms > 600) bad.push('раскрытие без хода высоты: ' + JSON.stringify(o1));
    await m.waitForTimeout(800);
    const o2 = await m.evaluate(() => { const e = document.querySelector('#s-notif .nt[data-id="n2"]'), q = s => e.querySelector(s), im = q('.nt__img'), ir = im.getBoundingClientRect(), er = e.getBoundingClientRect(), i2 = im.querySelector('img');
        return { open: e.classList.contains('is-open'), aria: q('.nt__head').getAttribute('aria-expanded'), nw: e.classList.contains('is-new'), h: Math.round(er.height), img: Math.round(ir.width) + '×' + Math.round(ir.height), imgW: Math.round(er.width - ir.width), loaded: i2.naturalWidth > 0, thumb: getComputedStyle(q('.nt__pic')).opacity, btn: ((q('.nt__btn') || {}).textContent || '').replace(/\s+/g, ' '), meta: q('.nt__meta').textContent.replace(/\s+/g, ' '), sClamp: Math.round(q('.nt__s').getBoundingClientRect().height) }; });
    if (!o2.open || o2.aria !== 'true' || o2.nw || o2.h < h0 + 150 || o2.imgW !== 28 || !o2.loaded || o2.thumb !== '0' || o2.btn !== 'В заведение' || !/Акция · .+ · Сегодня, 09:15/.test(o2.meta)) bad.push('раскрытая акция: ' + JSON.stringify(o2));
    const c1 = await m.evaluate(() => { const e = document.querySelector('#s-notif .nt[data-id="n2"]'); e.querySelector('.nt__head').click(); const an = e.getAnimations().find(x => x.effect.getKeyframes().some(k => k.height)); return { kf: an ? an.effect.getKeyframes().map(k => k.height) : null, closing: e.classList.contains('is-closing') }; });
    await m.waitForTimeout(600);
    const c2 = await m.evaluate(() => { const e = document.querySelector('#s-notif .nt[data-id="n2"]'); return { open: e.classList.contains('is-open'), closing: e.classList.contains('is-closing'), h: Math.round(e.getBoundingClientRect().height), aria: e.querySelector('.nt__head').getAttribute('aria-expanded'), an: e.getAnimations().length }; });
    if (!c1.kf || !c1.closing || c2.open || c2.closing || c2.h !== h0 || c2.aria !== 'false' || c2.an) bad.push('сворачивание: ' + JSON.stringify({ c1, c2, h0 }));
    out.push('акция: раскрылась (' + h0 + ' → ' + o2.h + ' px за ' + o1.ms + ' мс), картинка ' + o2.img + ', «' + o2.btn + '», точка погасла; свернулась обратно в ' + c2.h + ' px');
    // промокод: код, «Скопировать», срок, «В корзину»; истёкший — зачёркнут, без кнопок
    await m.evaluate(() => document.querySelector('#s-notif [data-act="notif-f"][data-id="promo"]').click()); await m.waitForTimeout(800);
    const p = await m.evaluate(() => { const all = [...document.querySelectorAll('#s-notif .nt')], old = document.querySelector('#s-notif .nt.is-old'); return { all: all.length, promo: document.querySelectorAll('#s-notif .nt--promo').length, old: old ? { till: old.querySelector('.nt__till').textContent.replace(/\s+/g, ' '), copy: !!old.querySelector('[data-act="notif-copy"]'), btn: !!old.querySelector('.nt__btn'), strike: getComputedStyle(old.querySelector('.tk__c')).textDecorationLine } : null }; });
    if (p.all !== 2 || p.promo !== 2 || !p.old || !/^Истёк/.test(p.old.till) || p.old.copy || p.old.btn || p.old.strike !== 'line-through') bad.push('промокоды: ' + JSON.stringify(p));
    await m.evaluate(() => document.querySelector('#s-notif .nt[data-id="n1"] .nt__head').click()); await m.waitForTimeout(700);
    await m.evaluate(() => document.querySelector('#s-notif .nt[data-id="n1"] [data-act="notif-copy"]').click()); await m.waitForTimeout(500);
    const cp = await m.evaluate(() => { const e = document.querySelector('#s-notif .nt[data-id="n1"]'); return { code: e.querySelector('.tk__c').textContent, till: e.querySelector('.nt__till').textContent.replace(/\s+/g, ' '), ok: !!e.querySelector('.tk__b.is-ok'), toast: document.getElementById('toast').textContent, btn: e.querySelector('.nt__btn').textContent.replace(/\s+/g, ' ') }; });
    if (cp.code !== 'CLEVER10' || !/^до \d/.test(cp.till) || !cp.ok || !/CLEVER10/.test(cp.toast) || cp.btn !== 'В корзину') bad.push('промокод: ' + JSON.stringify(cp));
    out.push('«Промо» — 2 карточки, истёкший зачёркнут и без кнопок; у действующего — код, срок, «Скопировать» (галочка и тост), «В корзину»');
