    if (!st.on || !st.nset || st.h2 !== 'Что присылать' || st.rows !== 4 || st.bottom < 14 || st.bottom > 70) bad.push('шторка настроек: ' + JSON.stringify(st));
    await m.evaluate(() => document.querySelector('#sheet .nts__set [data-id="news"]').click()); await m.waitForTimeout(200);
    const sv = await m.evaluate(() => JSON.parse(localStorage.getItem('clever2-nset') || '{}').news);
    if (sv !== 0) bad.push('настройка не запомнилась: ' + sv);
    await m.evaluate(() => document.querySelector('#sheet [data-act="close-sheet"]').click()); await m.waitForTimeout(700);
