    await m.evaluate(() => document.querySelector('#s-notif [data-act="notif-use"][data-id="n1"]').click()); await m.waitForTimeout(500);
    const us = await m.evaluate(() => __p.S.promo);
    if (us !== 'CLEVER10') bad.push('в корзину: ' + us);
