    const a = await m.evaluate(() => ({ sub: document.querySelector('#favScroll .favs__sub').textContent.replace(/\s+/g, ' '), grps: [...document.querySelectorAll('#favScroll .fgrp')].map(g => g.dataset.rest).join(), all: document.querySelectorAll('#favScroll .fgrp [data-act="fav-all"]').length, items: document.querySelectorAll('#favScroll .fgrp .item').length }));
    if (a.sub !== '3 блюда и 2 заведения' || a.grps !== 'dominos,terra,letitbe' || a.all !== 3 || a.items !== 3) bad.push('вид: ' + JSON.stringify(a));
    out.push(a.sub + ', группы ' + a.grps);
    await m.evaluate(() => document.querySelector('#favScroll [data-act="fav-all"][data-id="terra"]').click()); await m.waitForTimeout(700);
    const b = await m.evaluate(() => ({ rest: __p.S.cartRest, ids: __p.live().map(c => c.dish).join(), toast: document.getElementById('toast').textContent }));
    if (b.rest !== 'terra' || b.ids !== 'steak' || !/Terra/.test(b.toast)) bad.push('всё в заказ: ' + JSON.stringify(b));
    out.push('«Всё в заказ» — ' + b.ids + ' из Terra');
    await m.evaluate(() => document.querySelector('#favScroll .item[data-item="country"] .item__fav').click()); await m.waitForTimeout(1500);
    const c = await m.evaluate(() => ({ country: !!document.querySelector('#favScroll .item[data-item="country"]'), grps: [...document.querySelectorAll('#favScroll .fgrp')].map(g => g.dataset.rest).join(), sub: document.querySelector('#favScroll .favs__sub').textContent.replace(/\s+/g, ' ') }));
    if (c.country || c.grps !== 'terra,letitbe' || !/^2 блюда/.test(c.sub)) bad.push('убрали: ' + JSON.stringify(c));
    out.push('сердце у «Кантри» — ушла, группы ' + c.grps);
    await m.evaluate(() => document.querySelector('#favScroll [data-act="fav-tab"][data-id="rests"]').click()); await m.waitForTimeout(900);
    const d = await m.evaluate(() => ({ n: document.querySelectorAll('#favScroll .frest').length, fill: getComputedStyle(document.querySelector('#favScroll .frest__fav svg')).fill }));
    await m.evaluate(() => document.querySelector('#favScroll [data-act="fav-rest-out"][data-id="tempo"]').click()); await m.waitForTimeout(1500);
    const e = await m.evaluate(() => ({ n: document.querySelectorAll('#favScroll .frest').length, tempo: !!__p.S.favRest.tempo }));
    if (d.n !== 2 || /none/.test(d.fill) || e.n !== 1 || e.tempo) bad.push('заведения: ' + JSON.stringify(d) + ' → ' + JSON.stringify(e));
    out.push('заведения: 2 с сердцем → «Пицца Темпо» ушла, осталось ' + e.n);
    if (m._errs.length) bad.push('ошибки: ' + m._errs.join('; '));
    await m._close();
