    await m.waitForTimeout(1050);
    const b = await m.evaluate(() => { const c = document.getElementById('s-chat'), r = c.getBoundingClientRect(), inp = document.getElementById('chatInput');
        return { sheet: document.getElementById('sheet').classList.contains('is-on'), top: __p.S.stack[__p.S.stack.length - 1], x: Math.round(r.left), val: inp ? inp.value : null, msgs: document.querySelectorAll('#chatBox .msg').length,
            hit: (() => { const e = document.elementFromPoint(innerWidth / 2, r.top + 100); return !!e && c.contains(e); })() }; });
    if (a.sheet) bad.push('через 150 мс шторка ещё открыта');
