        if (r.fx !== want[fx] || (fx !== 'calm' && r.props !== 'opacity,transform')) bad.push('эффект ' + fx + ': ' + JSON.stringify(r));
        got.push(fx + ' — ' + r.fx.replace(/:.*/, ''));
