    await m.addInitScript(() => { if (sessionStorage.getItem('lk-once')) return; sessionStorage.setItem('lk-once', '1'); localStorage.removeItem('clever2-lk1011'); localStorage.removeItem('clever2-auth'); localStorage.setItem('clever2-fxv', JSON.stringify({ authic: 'lock', lock: 'solid', cnum: 'all' })); });
