    await m.evaluate(() => document.querySelector('[data-act="auth"]').click()); await m.waitForTimeout(1000);
    const s2 = await m.evaluate(() => ({ lock: (document.querySelector('#authLogo svg') || {}).dataset.lock, saved: JSON.parse(localStorage.getItem('clever2-fxv')).lock, flag: localStorage.getItem('clever2-lk1011') }));
    if (s2.lock !== 'shield' || s2.saved !== 'shield' || s2.flag !== '1') bad.push('разовый перенос на щит: ' + JSON.stringify(s2));
    out.push('«Сплошной» из «Вариантов» — по-прежнему с дужкой и зелёной кнопкой; сохранённый раньше замок разово сменился на щит');
