    const look = d => m.evaluate(d => { const st = document.querySelector('#s-cart .citem .stepper'), b = st.querySelector('[data-d="' + d + '"]'), g = st.querySelector('.press-grad'); return { n: st.querySelector('.num').textContent, held: b.classList.contains('is-held'), scale: +(+getComputedStyle(b).scale || 1).toFixed(2), grad: g ? (g.classList.contains('press-grad--r') ? 'r' : 'l') : '', op: g ? +(+getComputedStyle(g).opacity).toFixed(2) : 0 }; }, d);
