    if (!a.nw || a.nw.top < a.isles[2].bottom || a.nw.mapH < 120 || !a.nw.plus || T(a.nw.cap) !== 'Новый адрес') bad.push('фрагмент карты «Новый адрес»: ' + JSON.stringify(a.nw));
