        await m.evaluate(() => document.querySelector('#profileScroll [data-act="go-pay"]').click()); await m.waitForTimeout(1200);
        await m.evaluate(() => document.querySelector('#s-pay [data-act="card-add"]').click()); await m.waitForTimeout(1200);
        await m.evaluate(() => { window._rec = []; window._gn = 0; window._both = 0; window._stop = 0;
            new MutationObserver(ms => ms.forEach(q => q.addedNodes.forEach(n => { if (n.classList && n.classList.contains('sheet--ghost')) window._gn++; }))).observe(document.getElementById('sheet').parentNode, { childList: true });
            (function f() { const gh = document.querySelector('.sheet--ghost'), sh = document.getElementById('sheet'), e = gh || sh, go = e.querySelector('.sheet__foot .cta').getBoundingClientRect();
                if (gh && sh.style.opacity !== '0') window._both++;   // копия и настоящая видны разом
                window._rec.push(go.bottom); if (!window._stop) requestAnimationFrame(f); })(); });
        const p = await m.evaluate(() => { const b = document.getElementById('nc-num').getBoundingClientRect(); return { x: b.left + b.width / 2, y: b.top + b.height / 2 }; });
        const cdp = await m.context().newCDPSession(m); await m.waitForTimeout(200);
        await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: p.x, y: p.y, id: 1 }] }); await m.waitForTimeout(40);
        await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
