            for (let i = 1; i < a.length; i++) { const d = a[i] - a[i - 1]; if (d > .6) back = Math.max(back, d); if (Math.abs(a[i] - end) > 20 && Math.abs(a[i] - a[0]) > 6) { run = Math.abs(d) < .4 ? run + 1 : 0; stall = Math.max(stall, run); } }
