        const quick = await m.evaluate(() => { const t = document.querySelector('[data-hb]'); t.click(); const n1 = document.querySelectorAll('.fx__hb').length, on1 = t.classList.contains('is-on'), op = getComputedStyle(t.querySelector('svg')).opacity; t.click(); t.click(); t.click(); return { n1, on1, op, n2: document.querySelectorAll('.fx__hb').length, on2: t.classList.contains('is-on') }; });
