    const t1 = await tap(top);
    if (t1.on || !t1.hb || t1.par !== '' || t1.pieces < 2 || Math.abs(t1.dx) > .35 || Math.abs(t1.dy) > .35 || Math.abs(t1.dw) > .4 || Math.abs(t1.dh) > .4) bad.push('шапка витрины: ' + JSON.stringify({ on: t1.on, hb: t1.hb, par: t1.par, pieces: t1.pieces, dx: t1.dx, dy: t1.dy, dw: t1.dw, dh: t1.dh }));
    await m.waitForTimeout(3300);   // по умолчанию — «Молния в пепел» (2,8 с)
    const t2 = await m.evaluate(s => ({ n: document.querySelectorAll('.fx__hb').length, op: getComputedStyle(document.querySelector(s + ' svg')).opacity, on: document.querySelector(s).getAttribute('aria-pressed') }), top);
    if (t2.n || t2.op !== '1' || t2.on !== 'false') bad.push('шапка витрины, после эффекта: ' + JSON.stringify(t2));
