    if (!a) { await m._close(); return { pass: false, detail: 'поля «Имя и фамилия на карте» нет' }; }
    if (!a.last || a.label !== 'Имя и фамилия на карте' || a.ac !== 'cc-name' || a.cap !== 'characters' || a.fs < 16) bad.push('поле: ' + JSON.stringify(a));
