    const t = await m.evaluate(() => ({ val: document.getElementById('nc-name').value, face: document.querySelector('#ncCard .ncard__f .pcard__low b').textContent, dis: document.getElementById('ncAdd').disabled }));
    if (t.val.trim() !== 'IVAN SHCHUKIN-ZHUK' || t.face !== 'IVAN SHCHUKIN-ZHUK' || t.dis) bad.push('ввод имени: ' + JSON.stringify(t));
    out.push('без имени кнопка неактивна, после CVC курсор переходит к имени; «иван щукин-жук 7!» → «' + t.val.trim() + '», на карте то же, кнопка активна');
