    const hd = await m.evaluate(() => { const h = document.getElementById('authH'), sb = document.getElementById('authSub'), bk = document.getElementById('authBack');
        return { lines: h.innerText.split('\n').map(x => x.replace(/\s+/g, ' ').trim()).filter(Boolean), br: !!h.querySelector('br'), sub: sb.innerText.replace(/\s+/g, ' ').trim(), edit: /Изменить/.test(document.getElementById('sheet').innerText), back: bk ? { op: +getComputedStyle(bk).opacity, vis: getComputedStyle(bk).visibility } : null }; });
    if (hd.lines.join(' / ') !== 'Авторизация' || hd.br) bad.push('заголовок: ' + JSON.stringify(hd.lines));   // 17.11, вечер: «Просто Авторизация» — одной строкой
    if (hd.sub !== 'Введите ваш номер телефона, чтобы получить код для авторизации') bad.push('подпись: «' + hd.sub + '»');
