    out.push('заголовок «' + hd.lines.join(' / ') + '», подпись «' + hd.sub.slice(0, 18) + '…»; стрелки на шаге номера нет');
    await m.waitForTimeout(5000);
    const F = await m.evaluate(() => { window._stop = 1; return window._f.slice(); });
    // 18.11: капча — «лоток» поля: [5] — низ капчи от низа поля, [6] — разница краёв с полем
    const first = F[0], up = F.find(x => x[3] > .95 && x[2] <= 0 && x[5] >= 30 && x[5] <= 44 && x[6] <= .5), okF = F.find(x => x[4]), okT = okF ? okF[0] : 1e9, hid = F.find(x => x[0] > okT + 600 && x[3] < .05 && x[5] <= 0), last = F[F.length - 1];
