    if (!up) bad.push('капча не выдвинулась вплотную к полю (верх под полем, видно 30–44 px, с обводкой не шире поля — 20.11: «снизу торчит по пикселю с каждой стороны»): ' + JSON.stringify(F.filter(x => x[3] > .95).slice(-1)));
    const HD = F.filter(x => x[0] > okT + 1000 && (!hid || x[0] <= hid[0])); let jerk = 0; for (let i = 1; i < HD.length; i++) jerk = Math.max(jerk, HD[i][5] - HD[i - 1][5], (HD[i - 1][5] - HD[i][5]) - 12);
    if (jerk > 0) bad.push('задвигается рывком: ' + JSON.stringify(HD.map(x => x[5])));
    if (!okF || okT > 2000) bad.push('«Готово» — на ' + okT + ' мс');
    if (!hid || hid[0] - okT < 1500 || hid[0] - okT > 3200 || last[3] > .05 || last[5] > 0) bad.push('после «Готово» не спряталась под поле: ' + JSON.stringify([hid, last]));
    const G = F.filter(x => x[0] >= 900).map(x => x[1]), gm = G.length ? Math.max(...G) - Math.min(...G) : 99;
    if (gm > .5) bad.push('кнопка сдвигалась на ' + gm.toFixed(1) + ' px');
    out.push('капча: сначала под полем (низ ' + first[5] + ' px от низа поля), выдвинулась вплотную на ' + (up && up[0]) + ' мс (верх ' + (up && up[2]) + ' px под полем, видно ' + (up && up[5]) + ' px), «Готово» на ' + okT + ' мс, спряталась на ' + (hid && hid[0]) + ' мс; кнопка за ' + G.length + ' кадров не сдвинулась (' + gm.toFixed(1) + ' px)');
    // 19.11, позже: шаг кода «Свободно» (по умолчанию) — заголовок тот же, подпись «Введите код…», стрелки вверху нет, под кнопкой —
