        if (r.step !== 'phone' || r.act !== 'authPhone' || r.v !== '29 123-45-67' || r.bot > .05 || r.chg > .05 || r.lost.length) bad.push('«Изменить номер телефона»: ' + JSON.stringify(r));
        out.push('«Изменить номер» — шаг номера, курсор в поле, номер «' + r.v + '» на месте, капчи нет; фокус не терялся');
        // 19.11: номер уже меняли, снова — только после отсчёта: ссылки «Изменить номер телефона» нет
