        const mid = await m.evaluate(() => document.querySelectorAll('#fx .dls-fly').length); await m.waitForTimeout(800);
        const r = await m.evaluate(k => { const t = document.querySelector('#s-rest .ri-tk[data-k="' + k + '"]'), w = t.querySelector('.ri-lv, .ri-pk__bw');
            return { kind: window.__p.sheetKind, fly: document.querySelectorAll('#fx .dls-fly').length, dls: t.classList.contains('is-dls'), op: +getComputedStyle(w).opacity, sl: t.parentNode.scrollLeft }; }, k);
