            const tag = rid + ' ' + k, dish = rid === 'terra' && k === 'gift';
            const f = await tapFly(k);
            // 18.11: у скидки и подарка, пока шторка доезжает, из-за картинки вылетают разноцветные лучики (как «Искры» у галочки входа) и гаснут;
            // у плашки в это время ничего не гаснет
