    await m.keyboard.type('clever15');
    await m.evaluate(() => (document.querySelector('#s-cart .pcode .pfield__go') || document.querySelector('#s-cart .pcode [data-act="promo"]')).click()); await m.waitForTimeout(900);
    const c = await m.evaluate(() => { const d = document.querySelector('#s-cart .sum .disc'); return { promo: window.__p.S.promo, line: d ? d.textContent.replace(/\s+/g, ' ').trim() : '', mode: window.__p.S.mode }; });
    if (c.promo !== 'CLEVER15' || !/^Промокод навынос/.test(c.line) || c.mode !== 'pickup') bad.push('корзина: ' + JSON.stringify(c)); else out.push('корзина: clever15 → «' + c.line + '», «Заберу сам»');
    if (m._errs.length) bad.push('ошибки: ' + m._errs.join('; '));
