        const c = { v, has, base: /<base href="\/">/.test(src), ver: new RegExp("id: 'addr', name: 'Шторка адреса', v: '" + v.replace('.', '\\.') + "'").test(src), bld: (src.match(/var BUILD = '([^']*)'/) || [])[1] || '', errs: [] };
