    if (rows) { await m.evaluate(() => { document.querySelector('[data-act="perf"][data-id="fast"]').click(); document.querySelector('[data-act="fps"][data-id="1"]').click(); }); await m.waitForTimeout(1300); }
    const a = await m.evaluate(() => ({ perf: document.getElementById('app').dataset.perf, txt: (document.querySelector('.fpsm') || {}).textContent || '', on: (document.querySelector('[data-act="perf"][data-id="fast"]') || { getAttribute: () => '' }).getAttribute('aria-pressed') }));
    await m.reload(); await m.waitForTimeout(900); if (await m.isVisible('#splash')) await m.tap('#splash'); await m.waitForTimeout(1500);
    const b = await m.evaluate(() => ({ perf: document.getElementById('app').dataset.perf, fps: !!document.querySelector('.fpsm') }));
