// «стекло под соседом»: элемент с размытием фона (backdrop-filter), которого перекрывает сосед, стоящий выше (z-index).
// В Safari размытый элемент — отдельный слой композитора, и такой сосед может оказаться ПОД стеклом (04.11: в «Популярном»
// матовая капсула с числом оценок легла поверх цветной — «★ 4,» и обрезанная «7»). Смотрим только видимое на экране и только соседей,
// которые что-то рисуют (пустой слой эффектов не в счёт; спрятанные за край панели — тоже). Стекло у родителя, а поверх — его дети — так можно: дети всегда выше
function glassScan() {
    const out = [];
    const vis = x => { for (let y = x; y && y !== document.body; y = y.parentElement) { const c = getComputedStyle(y); if (+c.opacity === 0 || c.visibility === 'hidden' || c.display === 'none') return false; } return x.getClientRects().length > 0; };
    const z = e => { const c = getComputedStyle(e); return c.position === 'static' && !/flex|grid/.test(getComputedStyle(e.parentElement).display) ? 0 : (parseInt(c.zIndex) || 0); };
    const paints = s => { const c = getComputedStyle(s); return s.children.length > 0 || s.textContent.trim() !== '' || !/^(transparent|rgba\(0, 0, 0, 0\))$/.test(c.backgroundColor) || c.backgroundImage !== 'none' || c.boxShadow !== 'none' || parseFloat(c.borderTopWidth) > 0; };
    const clip = q => ({ left: Math.max(0, q.left), top: Math.max(0, q.top), right: Math.min(innerWidth, q.right), bottom: Math.min(innerHeight, q.bottom) });   // за краем экрана — не в счёт (спрятанные панели)
    const name = e => (e.id ? '#' + e.id : '') + (typeof e.className === 'string' && e.className ? '.' + e.className.trim().split(/\s+/).join('.') : e.tagName.toLowerCase());
    for (const e of document.querySelectorAll('body *')) {
        const cs = getComputedStyle(e), bf = cs.backdropFilter || cs.webkitBackdropFilter || 'none';
        if (bf === 'none' || !vis(e)) continue;
        const r = clip(e.getBoundingClientRect()); if (r.right - r.left < 1 || r.bottom - r.top < 1) continue;   // только то, что на экране
        for (const s of e.parentElement.children) {
            if (s === e || !vis(s) || !paints(s) || (getComputedStyle(s).backdropFilter || 'none') !== 'none') continue;
            const q = clip(s.getBoundingClientRect()), ox = Math.min(r.right, q.right) - Math.max(r.left, q.left), oy = Math.min(r.bottom, q.bottom) - Math.max(r.top, q.top);
            if (ox > 1 && oy > 1 && z(s) > z(e)) out.push(name(e) + ' ← ' + name(s) + ' (' + Math.round(ox) + '×' + Math.round(oy) + ' px)');
        }
    }
    return [...new Set(out)];
}
test('Safari: стекло (размытие фона) не лежит под соседом сверху — слои не перепутаются', '«Что-то непонятное с рейтингом пиццы Кантри в популярных. Отследи, как такое получилось, и подправь, чтобы в дальнейшем не было» (04.11, скриншот: матовая капсула «198» поверх зелёной «★ 4,7» — видна только «★ 4,»). Причина: размытие было у капсулы с числом, а цветная лежала над ней только по z-index; в Safari размытый элемент — отдельный слой, и в «Популярном» (лента внутри прокрутки) порядок перевернулся. Chrome так не ошибается, поэтому проверяем разметку: нигде нет видимого элемента с backdrop-filter, которого перекрывает сосед с бо́льшим z-index (стекло — у родителя, поверх — дети). Экраны: главная, «Доминос» (верх с «Популярным» и раздел пицц), шторка блюда «Кантри», шторка «Оценки», Terra. Сама проверка — на образце прежней разметки (две капсулы, стекло у нижней): должна его найти', async () => {
    const bad = [], seen = {};
    const m = await open();
    // образец прежней разметки — проверка обязана его найти (иначе она ослепла)
    await m.evaluate(() => { const d = document.createElement('div'); d.id = 'glassSample'; d.style.cssText = 'position:absolute;left:10px;top:300px;z-index:5;display:flex;height:21px';
        d.innerHTML = '<span style="position:relative;z-index:1;width:40px;background:#2e8b3d;border-radius:11px">4,7</span><span style="margin-left:-11px;width:40px;background:rgba(0,0,0,.5);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)">198</span>';
        document.getElementById('app').appendChild(d); });
    const sample = await m.evaluate(glassScan);
    await m.evaluate(() => document.getElementById('glassSample').remove());
    if (!sample.length) bad.push('образец прежней разметки не найден — проверка ослепла');
    const look = async key => { seen[key] = await m.evaluate(glassScan); };
    await look('главная');
    await m.evaluate(() => document.querySelector('[data-act="open-rest"][data-id="dominos"]').click()); await m.waitForTimeout(1600);
    await look('«Доминос», верх');
    await m.evaluate(() => { const sc = document.getElementById('restScroll'), c = document.querySelector('#s-rest .grid2 .item[data-item="country"]'); sc.scrollTop += c.getBoundingClientRect().top - 300; sc.dispatchEvent(new Event('scroll')); }); await m.waitForTimeout(700);
    await look('«Доминос», пиццы');
    await m.evaluate(() => [...document.querySelectorAll('#s-rest [data-act="open-dish"][data-id="country"]')].find(x => x.getClientRects().length).click()); await m.waitForTimeout(1100);
    await look('шторка блюда');
    await m.evaluate(() => document.querySelector('#sheet .dish__rb--pic').click()); await m.waitForTimeout(800);
    await look('шторка «Оценки»');
    await m.evaluate(() => document.querySelector('#sheet [data-act="close-sheet"]').click()); await m.waitForTimeout(700);
    await m.evaluate(() => document.querySelector('#s-rest [data-act="back"]').click()); await m.waitForTimeout(700);
    await m.evaluate(() => document.querySelector('[data-act="open-rest"][data-id="terra"]').click()); await m.waitForTimeout(1600);
    await look('Terra');
    // и сам бейдж: стекло — у кнопки, у капсулы с числом своего нет
    const rb = await m.evaluate(() => { const b = document.querySelector('#s-rest .pop-row .item__rate.rbadge--cnt') || document.querySelector('#s-rest .item__rate.rbadge--cnt'); if (!b) return null;
        const f = e => getComputedStyle(e).backdropFilter || getComputedStyle(e).webkitBackdropFilter || 'none';
        return { own: f(b), kids: [...b.querySelectorAll('*')].map(f).filter(v => v !== 'none').length }; });
    if (!rb || !/blur/.test(rb.own) || rb.kids) bad.push('бейдж рейтинга: стекло у кнопки — ' + (rb ? rb.own : 'нет бейджа') + ', у вложенных — ' + (rb ? rb.kids : '—'));
    for (const k in seen) if (seen[k].length) bad.push(k + ': ' + seen[k].join('; '));
    const e = m._errs.slice(); await m._close();
    if (e.length) bad.push('ошибки: ' + e.join('; '));
    return { pass: !bad.length, detail: 'образец прежней разметки найден: ' + (sample[0] || '—') + '; экраны: ' + Object.keys(seen).map(k => k + ' — ' + (seen[k].length ? seen[k].length + ' ✗' : 'чисто')).join(', ') + '; бейдж: стекло у кнопки (' + (rb ? rb.own : '—') + '), у капсулы с числом — нет' + (bad.length ? '; ✗ ' + bad.join('; ') : '') };
});
test('метка «Хит» — кубок, не звезда (звезда — у рейтинга рядом)', '«вижу конфликт — звёздочка в бейдже Хит и звёздочка снизу (рейтинг блюда); в хите должна быть другая иконка — например, кубок аккуратный, или что-то ещё — предложи». По умолчанию у «Хит» — кубок; в «Вариантах» («Значок «Хит»») — корона, медаль, палец вверх и звезда (как было); в шторке блюда — тот же значок', async () => {
    const m = await open(), bad = [];
    await m.evaluate(() => document.querySelector('[data-act="open-rest"][data-id="terra"]').click()); await m.waitForTimeout(1400);
    const look = () => m.evaluate(() => { const t = [...document.querySelectorAll('#s-rest .item .tag--hit')].find(x => x.getClientRects().length), u = t && t.querySelector('use'), sv = t && t.querySelector('svg');
        return { href: u ? u.getAttribute('href') : null, w: sv ? +sv.getBoundingClientRect().width.toFixed(1) : 0, n: document.querySelectorAll('#s-rest .tag--hit').length }; });
    const a = await look();
    if (a.href !== '#i-medal' || !(a.w >= 10)) bad.push('по умолчанию: ' + JSON.stringify(a));   // 10.11: по умолчанию — «Медаль» (выбор владельца)
    const seen = {};   // вариант — через localStorage и перезагрузку
    for (const v of ['crown', 'star', 'cup']) { await m.evaluate(v => localStorage.setItem('clever2-fxv', JSON.stringify({ hit: v })), v); await m.reload(); await m.waitForTimeout(1500);
        await m.evaluate(() => document.querySelector('[data-act="open-rest"][data-id="terra"]').click()); await m.waitForTimeout(1400); seen[v] = (await look()).href; }
    if (seen.crown !== '#i-crown' || seen.star !== '#i-star' || seen.cup !== '#i-cup') bad.push('варианты: ' + JSON.stringify(seen));
    await m.evaluate(() => localStorage.setItem('clever2-fxv', '{}')); await m.reload(); await m.waitForTimeout(1500);
    await m.evaluate(() => document.querySelector('[data-act="open-rest"][data-id="terra"]').click()); await m.waitForTimeout(1400);
    await m.evaluate(() => [...document.querySelectorAll('#s-rest [data-act="open-dish"][data-id="steak"]')].find(x => x.getClientRects().length).click()); await m.waitForTimeout(1100);
    const ds = await m.evaluate(() => { const u = document.querySelector('#sheet .tag--hit use'); return u ? u.getAttribute('href') : null; });
    if (ds !== '#i-medal') bad.push('шторка блюда: ' + ds);
    const e = m._errs; await m._close(); if (e.length) bad.push('ошибки: ' + e.join('; '));
    return { pass: !bad.length, detail: 'по умолчанию — ' + a.href + ' (' + a.w + ' px), меток «Хит» в меню ' + a.n + '; корона — ' + seen.crown + ', как было — ' + seen.star + ', кубок — ' + seen.cup + '; шторка блюда — ' + ds + (bad.length ? '; ✗ ' + bad.join('; ') : '') };
});
test('витрина: значки — «назад» по высоте сердца, «поделиться» телом как сердце', '«иконку поделиться — чуть больше: её тело не соответствует сердцу», «иконку назад — по высоте сердца». По пикселям (снимок значка ×4): на обложке и на панели высота «назад» = высоте сердца (±0,6 px), «поделиться» — не ниже сердца больше чем на 1 px', async () => {
    const m = await open({ dpr: 4 });
    await m.evaluate(() => document.querySelector('[data-act="open-rest"][data-id="terra"]').click()); await m.waitForTimeout(1300);
    await m.addStyleTag({ content: '#rtop .ibtn--glass, #rtop .rtop__acts { background: #fff !important; -webkit-backdrop-filter: none !important; backdrop-filter: none !important; box-shadow: none !important; } #rtop svg { color: #000 !important; fill: none !important; }' });
    const meas = async () => { const o = {}; for (const a of ['back', 'fav-rest', 'share']) { let el = null; for (const e of await m.$$('#rtop [data-act="' + a + '"] svg')) if (await e.isVisible()) el = e;
        const P = pngRead(await el.screenshot()); let t = P.h, b = -1; for (let y = 0; y < P.h; y++) for (let x = 0; x < P.w; x++) { const p = P.px(x, y); if (p[0] + p[1] + p[2] < 420) { if (y < t) t = y; if (y > b) b = y; } }
        o[a] = (b - t + 1) / 4; } return o; };
    const hero = await meas();
    for (let y = 100; y <= 400; y += 100) await m.evaluate(y => { const sc = document.getElementById('restScroll'); sc.scrollTop = y; sc.dispatchEvent(new Event('scroll')); }, y);
    await m.evaluate(() => { const sc = document.getElementById('restScroll'); sc.scrollTop = 380; sc.dispatchEvent(new Event('scroll')); }); await m.waitForTimeout(700);
    const bar = await meas();
    await m._close();
    const ok = o => Math.abs(o.back - o['fav-rest']) <= .6 && o.share >= o['fav-rest'] - 1;
    const d = o => '«назад» ' + o.back + ', сердце ' + o['fav-rest'] + ', «поделиться» ' + o.share + ' px';
    return { pass: ok(hero) && ok(bar), detail: 'на обложке: ' + d(hero) + (ok(hero) ? '' : ' ✗') + '; на панели: ' + d(bar) + (ok(bar) ? '' : ' ✗') };
});
test('витрина: «поделиться» — текст и ссылка на карточку заведения, без системного экрана — копия', '«отправляется название заведения, картинка и классный текст, на который хочется нажать». Касание зовёт системный экран «Поделиться» (navigator.share): живой текст («Давай закажем?», рейтинг, время, акция) и ссылка на r/<id>.html — по её разметке мессенджер рисует превью с картинкой; закрыли экран — тихо; где его нет — копируем текст со ссылкой и сообщаем', async () => {
    const m = await open();
    await m.evaluate(() => { window._shared = []; navigator.share = d => { window._shared.push(d); return Promise.resolve(); }; });
    await m.evaluate(() => document.querySelector('[data-act="open-rest"][data-id="dominos"]').click()); await m.waitForTimeout(1300);
    await m.evaluate(() => document.querySelector('#s-rest [data-act="share"]').click()); await m.waitForTimeout(400);
    const a = await m.evaluate(() => ({ n: window._shared.length, d: window._shared[0] || {}, toast: (document.getElementById('toast') || {}).textContent || '' }));
    await m.evaluate(() => { navigator.share = () => Promise.reject(Object.assign(new Error('cancel'), { name: 'AbortError' })); document.getElementById('toast').textContent = ''; });
    await m.evaluate(() => document.querySelector('#s-rest [data-act="share"]').click()); await m.waitForTimeout(400);
    const b = await m.evaluate(() => (document.getElementById('toast') || {}).textContent || '');
    await m.evaluate(() => { Object.defineProperty(navigator, 'share', { value: undefined, configurable: true }); document.getElementById('toast').textContent = ''; });
    await m.evaluate(() => document.querySelector('#s-rest [data-act="share"]').click()); await m.waitForTimeout(400);
    const c = await m.evaluate(() => (document.getElementById('toast') || {}).textContent || '');
    const e = m._errs; await m._close();
    const pass = a.n === 1 && a.d.url === 'https://clever-newdiz.onrender.com/r/dominos.html' && a.d.title === 'Доминос пицца — Clever.by' && /^Давай закажем\? .+«Доминос пицца» — ★ 4,7, привезут за 30–45 мин, а сейчас −30% на комбо/.test(a.d.text || '') &&
        !/скопирована/.test(a.toast) && !/скопирована/.test(b) && /скопирована/.test(c) && !e.length;
    return { pass, detail: 'системный экран: ' + (a.n ? '«' + a.d.text + '» + ' + a.d.url : 'не вызван ✗') + '; отмена — ' + (b ? '«' + b + '» ✗' : 'тихо') + '; без него — «' + (c || '—') + '»' + (e.length ? '; ошибки: ' + e.join('; ') : '') };
});
test('ссылка «Поделиться»: страницы r/<id>.html с превью и картинки 1200×630 у всех заведений; по ссылке — сразу заведение', 'превью в мессенджере строится по разметке Open Graph страницы ссылки: название, описание, картинка. У каждого заведения есть r/<id>.html (og:title с названием, og:description, og:image на img/og/<id>.jpg) и сама картинка 1200×630; страница ведёт в приложение на #rest=<id>, приложение сразу открывает заведение (и у того, кто здесь впервые, — без шторки города), метку из адреса убирает', async () => {
    const html = fs.readFileSync(URL.replace('file://', ''), 'utf8'), RESTS = new Function('return ' + /var RESTS = (\[[\s\S]*?\n    \]);/.exec(html)[1])();
    const jpgSize = f => { const d = fs.readFileSync(f); for (let i = 2; i < d.length;) { const mk = d[i + 1], len = d.readUInt16BE(i + 2); if (mk >= 0xC0 && mk <= 0xC3) return d.readUInt16BE(i + 7) + '×' + d.readUInt16BE(i + 5); i += 2 + len; } return '?'; };
    const bad = [];
    RESTS.forEach(r => {
        const p = path.join(ROOT, 'r', r.id + '.html'), j = path.join(ROOT, 'img', 'og', r.id + '.jpg');
        if (!fs.existsSync(p)) return bad.push(r.id + ': нет страницы');
        const t = fs.readFileSync(p, 'utf8');
        if (!t.includes('<meta property="og:title" content="' + r.name.replace(/&/g, '&amp;') + ' — Clever.by">')) bad.push(r.id + ': og:title');
        if (!/<meta property="og:description" content="★ [\d,]+ · привезут за /.test(t)) bad.push(r.id + ': og:description');
        if (!t.includes('<meta property="og:image" content="https://clever-newdiz.onrender.com/img/og/' + r.id + '.jpg">')) bad.push(r.id + ': og:image');
        if (!t.includes('location.replace("../#rest=' + r.id + '")')) bad.push(r.id + ': переход');
        if (!fs.existsSync(j)) bad.push(r.id + ': нет картинки'); else if (jpgSize(j) !== '1200×630') bad.push(r.id + ': картинка ' + jpgSize(j));
    });
    // по ссылке — сразу заведение, и у того, кто здесь впервые
    const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, locale: 'ru-RU' }), m = await ctx.newPage(), errs = [];
    m.on('pageerror', e => errs.push(e.message));
    await m.route(/unpkg\.com\/maplibre-gl/, r => r.fulfill({ body: MAPLIB, contentType: 'application/javascript' }));
    await m.route(/tiles\.openfreemap\.org/, r => r.fulfill({ body: STYLE, contentType: 'application/json' }));
    await m.route(/nominatim\.openstreetmap\.org/, nominatim);
    await m.goto(URL + '#rest=terra'); await m.waitForTimeout(2000);
    const g = await m.evaluate(() => ({ rest: document.getElementById('s-rest').classList.contains('is-on'), title: (document.querySelector('#s-rest .rtop__title') || {}).textContent, hash: location.hash, city: document.getElementById('sheet').classList.contains('is-on') }));
    await ctx.close();
    const pass = !bad.length && g.rest && g.title === 'Terra' && !g.hash && !g.city && !errs.length;
    return { pass, detail: 'страниц и картинок: ' + RESTS.length + (bad.length ? ' — ' + bad.join('; ') + ' ✗' : ', всё на месте') + '; #rest=terra у нового человека: ' + (g.rest ? 'открылась «' + g.title + '»' : 'не открылась ✗') + (g.hash ? ', метка осталась ✗' : ', метка убрана') + (g.city ? ', шторка города ✗' : '') + (errs.length ? '; ошибки: ' + errs.join('; ') : '') };
});

(async () => {
    const only = process.argv[2] ? process.argv[2].toLowerCase() : '';
    browser = await pw.chromium.launch({ args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
    let fail = 0, n = 0;
    for (const t of TESTS) {
        if (only && (only[0] === '-' ? t.name.toLowerCase().includes(only.slice(1)) : !t.name.toLowerCase().includes(only))) continue;
        if (process.env.RE && !new RegExp(process.env.RE, 'i').test(t.name)) continue;     // RE='^вход|^поиск' — только эти
        if (process.env.SKIP && new RegExp(process.env.SKIP, 'i').test(t.name)) continue;   // SKIP='адрес|карт' — кроме этих
        n++;
        let r; try { r = await t.fn(); } catch (e) { r = { pass: false, detail: 'упал: ' + e.message.split('\n')[0] }; }
        if (!r.pass) fail++;
        if (open.retries) { r.detail += ' [стенд: варианты записаны повторно — ' + open.retries + ' раз]'; open.retries = 0; }
        console.log((r.pass ? '✓ ' : '✗ ') + t.name + '\n    ' + r.detail + (r.pass ? '' : '\n    зачем: ' + t.why));
    }
    await browser.close();
    console.log('\n' + (fail ? '✗ не прошли: ' + fail + ' из ' + n : '✓ все ' + n + ' проверок прошли'));
    process.exit(fail ? 1 : 0);
})();
